import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"3.0.0-WP-severe-fix-and-closure","description":"","frontmatter":{},"headers":[],"relativePath":"release/3.0.0-WP-severe-fix-and-closure.md","filePath":"release/3.0.0-WP-severe-fix-and-closure.md"}'),s={name:"release/3.0.0-WP-severe-fix-and-closure.md"};function d(i,e,c,l,n,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-0-0-wp-severe-fix-and-closure" tabindex="-1">3.0.0-WP-severe-fix-and-closure <a class="header-anchor" href="#_3-0-0-wp-severe-fix-and-closure" aria-label="Permalink to &quot;3.0.0-WP-severe-fix-and-closure&quot;">​</a></h1><p><strong>2026-11-26 · build 529 · SHA256 见下表</strong></p><p>严重修复与收口工作包：上一包交付实测发现的五项严重问题全部根因化关闭—— VMware 启动龟速根因、K-08（ush 横幅 uname 偶发竞态）、K-09（E2E 测试失败 &quot;网络&quot;误诊）、K-10（OCIRE UEFI 轨单字符 &#39;!&#39; 死）、update 全链路断裂—— 外加两个本包实测新抓的回归（oc.splash=0 诊断路径、OTA 下载空窗中断）， 零&quot;已知问题&quot;逃避，全量证据在最终发布字节上重跑。</p><h2 id="_1-vmware-启动龟速根因-b-vmx1" tabindex="-1">① VMware 启动龟速根因（B-vmx1） <a class="header-anchor" href="#_1-vmware-启动龟速根因-b-vmx1" aria-label="Permalink to &quot;① VMware 启动龟速根因（B-vmx1）&quot;">​</a></h2><ul><li><strong>根因不是期限而是负载</strong>：VMware 下每一次 inb/MMIO 读都是一次 VM exit （1–3 µs），而热轮询循环每迭代一次读一个端口且无空闲节拍；另有一个 以 4096 <strong>迭代次数</strong>（QEMU 上几微秒、VMware 上 10+ ms 的 exit 时间）判定 &quot;命令丢弃&quot;的启发式——每个启动偏慢的健康虚拟盘都会被判死、中止、 20000 次 io_wait 空转、再在 1000 ms 期限内重试至多 8 次：分钟级启动。</li><li><strong>修复</strong>：<code>driver_tsc_pause_us()</code>（零端口 I/O 的 TSC 微秒自旋）为全部热 轮询配速（BMDMA 25 µs、ATA status/AC97 codec/HDA stream/e1000 EEPROM 每 50 µs 一读）；丢弃判定改为<strong>真实时间门</strong>（10 ms 墙钟 BMIS==0 且 task file 空闲——QEMU 上真丢弃仍会空满期限、健康传输永不空这么久）； 20000 次 io_wait 空转改 2 ms TSC 停顿；OCBL 菜单循环（两味）在 int16h/LSR/CMOS 轮询之间纯 CPU 停顿；早期控制台 COM1 THRE 等待有界。</li><li><strong>新证据面</strong>：内核在每次 L1_READY 时打印 <code>[perf] ata_dma: port_io=... polls=... xfers=... retries=... drops=... wait_ms=...</code>。 QEMU TCG 实测（16 MiB FAT32 /etc 盘、45 次 DMA 传输、修复前后计数对比）： port_io <strong>17,608,313 → 39,452（446 倍）</strong>，菜单迭代 <strong>130,589 → 117 （1116 倍）</strong>。VMware 上每个计数操作即一次 VM exit：修复前 18–53 秒纯 exit 处理 + 假丢弃重试风暴（分钟级），修复后 0.04–0.12 秒。</li><li>证据：<code>evidence/wp-severe-fix-and-closure/b-vmx1-vmware-performance.md</code>。</li></ul><h2 id="_2-k-08-ush-横幅-uname-偶发竞态-按构造关闭" tabindex="-1">② K-08：ush 横幅 uname 偶发竞态（按构造关闭） <a class="header-anchor" href="#_2-k-08-ush-横幅-uname-偶发竞态-按构造关闭" aria-label="Permalink to &quot;② K-08：ush 横幅 uname 偶发竞态（按构造关闭）&quot;">​</a></h2><ul><li><strong>根因（monitor hunter + 2.7 GB 中断 trace 实况捕获）</strong>： <code>l1_launcher_boot_default()</code> 在 <code>user_process_create()</code> 返回并 <code>boot_state_advance()</code> 打印<strong>之后</strong>才注册 <code>g_l1_entry_pid</code>，而 launcher 内核线程此时已就绪——该窗口内一次定时器抢占使 ush 在 pid 存在之前跑到 首个系统调用，L1_READY 一次性钩子 pid 比对失败，splash 钩子吞掉整个 横幅与首个提示符（ush 本体健康地等待输入）。</li><li><strong>三层修复</strong>：(1) 根因——创建 + 注册收进同一段关中断窗口（单 CPU 设计 中定时器 IRQ 是唯一抢占源）；(2) 第二道防线——<code>g_l1_entry_pid==0</code> 期间任意 pid 的首个系统调用触发一次性钩子；(3) 症状层——uname 操作 改为与 LANG_GET 同形的纯缓冲填充（横幅路径不再有 kcap 控制台捕获）。</li><li><strong>验收</strong>：默认 splash 启动（竞态主场）连续 <strong>20/20</strong> 横幅真实版本串、 <code>uname -r</code> 精确、<code>uname -a</code> 完整、零 panic。</li><li>证据：<code>evidence/wp-severe-fix-and-closure/b-k08-uname-race.md</code>。</li></ul><h2 id="_3-k-09-e2e-测试失败-沙箱网络-误诊-以计数器推翻" tabindex="-1">③ K-09：E2E 测试失败&quot;沙箱网络&quot;误诊（以计数器推翻） <a class="header-anchor" href="#_3-k-09-e2e-测试失败-沙箱网络-误诊-以计数器推翻" aria-label="Permalink to &quot;③ K-09：E2E 测试失败&quot;沙箱网络&quot;误诊（以计数器推翻）&quot;">​</a></h2><ul><li><strong>网络栈以自身计数器证明健康</strong>（netstat：DHCP 已服务、ARP 1 应答、 ICMP 4/4、TCP 1、明文 HTTP 下载保存 24 字节）+ 一次<strong>真实 TLS 1.2 DHE-RSA-AES128-SHA256 会话</strong>（加密 GET 已服务、close_notify 双向观察）。</li><li><strong>真缺陷四个</strong>：(1) 一次性 TLS 测试服务器死于内核 TLS1.3 优先 hello （服务器现循环 accept 到一个完整会话）；(2) <code>-serial mon:stdio</code> 台架 通道在本沙箱可测地饿死 QEMU 主循环（同 ISO 在 unix-socket 串口下 ping 4/4——两个 E2E 运行器全部改走 unix-socket）；(3) 陈旧提示符匹配把下一条 命令射进仍在执行的命令；(4) <strong>真实内核缺陷——COM1 RX 边沿丢失窗口</strong> （16550 在 8259 边沿触发输入后面电平保持 INTR，突发落进服务窗口不再 产生新边沿，剩余字节滞留 FIFO——粘贴的长命令行整行丢失）：以 10 ms tick 兜底 RX 轮询修复。</li><li><strong>验收</strong>：HTTPS E2E <strong>8/8</strong>、SSH E2E 出站场景 PASS（ssh-auth + ssh-exec）。 入站 sshd（宿主 paramiko → 客内 sshd）是唯一余留边界（pcap + monitor 转储 + TX-errors 计数器证据，KNOWN_ISSUES 诚实记录）。</li><li>证据：<code>evidence/wp-severe-fix-and-closure/b-k09-e2e-network.md</code>。</li></ul><h2 id="_4-k-10-ocire-uefi-轨单字符-之死-关闭" tabindex="-1">④ K-10：OCIRE UEFI 轨单字符 &#39;!&#39; 之死（关闭） <a class="header-anchor" href="#_4-k-10-ocire-uefi-轨单字符-之死-关闭" aria-label="Permalink to &quot;④ K-10：OCIRE UEFI 轨单字符 &#39;!&#39; 之死（关闭）&quot;">​</a></h2><ul><li><strong>根因</strong>：<code>tools/build_ocire_iso.sh</code> 把 <code>build/ocbl/ocbl_x64.efi</code>（入口 RVA 是 post-EBS 裸入口，期待 RCX=handoff/RDX=魔数）直接当作 BOOTX64.EFI 摆放——OVMF 的 StartImage 以 EFI ABI 到达，OCBL 入口即死，串口只留一个 &#39;!&#39;（ABI 违例标记）。修复：恢复盘 ISO 摆放主 ISO 的链条 （BOOTX64.EFI = OCRMECL PE、/OCBL.EFI = OCBL、El Torito = OCRMECL 复合）。</li><li><strong>验收</strong>：OCIRE 电池 <strong>14/14</strong>——七个 UEFI 场景全绿，为该电池存在以来 首次。</li><li>证据：<code>evidence/wp-severe-fix-and-closure/b-k10-ocire-uefi.md</code>。</li></ul><h2 id="_5-update-全链路-l1-程序-→-网络下载-ota-→-a-b-槽位-→-刷写" tabindex="-1">⑤ update 全链路（L1 程序 → 网络下载 OTA → A/B 槽位 → 刷写） <a class="header-anchor" href="#_5-update-全链路-l1-程序-→-网络下载-ota-→-a-b-槽位-→-刷写" aria-label="Permalink to &quot;⑤ update 全链路（L1 程序 → 网络下载 OTA → A/B 槽位 → 刷写）&quot;">​</a></h2><ul><li><strong>全链电池 <code>tools/abchain_e2e.py</code>（unix-socket 串口）10/10</strong>：GRUB 自举 A/B 盘从槽 A 启动 → <code>dhcp</code> → <code>config set update_url</code> → <code>update --status</code>（current boot: A / A/B disk: present）→ L1 <code>update</code> 向导五步 （网络 → A/B 盘 → <strong>IP 字面量直解</strong> → manifest → 确认安装：下载 1387 KB → SHA256 验证 → 解包刷入 B 槽 → set boot B → &quot;reboot required&quot;）→ 确认重启 → **BOOT_SLOT=B + 包内核横幅 + <code>uname -r</code> 包版本 <ul><li><code>update --status</code> current/next boot: B（确认提升）**。</li></ul></li><li><strong>宿主侧字节铁证</strong>：刷写后 B 槽 <code>/boot/opencube.elf</code> 与包内 <code>kernel/opencube.elf</code> sha256 逐字节一致，A 槽与种子内核一致。</li><li><strong>链上抓到并修复的真断点四个</strong>：(1) 向导 DNS 门拒绝 IP 字面量服务器 （<code>net_cmd_dns</code> 现直解 IP 字面量）；(2) 测试 manifest 字段名与生产格式 漂移（<code>sha256</code> vs 生产 <code>package_sha256</code>——电池现在以生产字段名从真实 包重生成 manifest，永久盯防此类漂移）；(3) <code>dhcp</code> 违反 RFC 2131——单发 DISCOVER + ~500 ms 窗口把健康局域网约 8 次启动 1 次报成超时（DISCOVER 与 REQUEST 现各重传 3 次 × 800 ms 墙钟）；(4) <strong>OTA 下载空窗中断</strong>—— <code>net_recv</code> 内部仅等 ~1.5 s 无数据即返回 -1，下载循环 <code>n&lt;=0</code> 立即放弃 （1.4 MB ≈ 350 个窗口，任一空窗全盘报废，本电池两轮一遇）：现以 <strong>30 s 无进展期限</strong>持续重试（header 与 body 双阶段、TLS 与明文双路径， 死连接仍在期限处诚实退出、永不挂死）。</li><li>证据：<code>evidence/wp-severe-fix-and-closure/b-update-chain.md</code> + <code>release/update-chain-transcript.txt</code>（完整成功串口日志）。</li></ul><h2 id="_6-本包实测新抓的两个回归-一并修复" tabindex="-1">⑥ 本包实测新抓的两个回归（一并修复） <a class="header-anchor" href="#_6-本包实测新抓的两个回归-一并修复" aria-label="Permalink to &quot;⑥ 本包实测新抓的两个回归（一并修复）&quot;">​</a></h2><ul><li><strong>oc.splash=0 诊断路径死机（K-08 修复引入）</strong>：<code>boot_splash_finish()</code> 缺 <code>g_splash_on</code> 检查——无 splash 启动时 begin 从未保存 hook 链，finish 却把零初始化的 {NULL,NULL} 恢复进控制台钩子槽，杀死串口 transcript （31/31 门禁在诊断 ISO 上当场抓住：boot 到 &quot;L1 isolation verified&quot; 后 ush 横幅与提示符消失）。修复：finish 只收自己开过的 splash。</li><li><strong>K-07 英文版条目中文残留</strong>：KNOWN_ISSUES 英文版中 K-07 段落曾被直接 写成中文（双语纪律破损）——已翻译为英文，中文镜像补齐 K-07–K-10。</li></ul><h2 id="_4-全量回归-全部在最终发布字节-build-529-上" tabindex="-1">4. 全量回归（全部在最终发布字节 build 529 上） <a class="header-anchor" href="#_4-全量回归-全部在最终发布字节-build-529-上" aria-label="Permalink to &quot;4. 全量回归（全部在最终发布字节 build 529 上）&quot;">​</a></h2><ul><li><code>make all</code>：0 错误 0 编译警告。</li><li><code>make test-strict</code>：BIOS（SeaBIOS）+ UEFI（OVMF）双轨 <code>-cpu qemu64,enforce -machine vmport=off -boot strict=on</code> <strong>双绿</strong> （OCRMECL → OCBL → 内核 → ush&gt;）。</li><li>31/31 回归（/NOSPLASH.TXT 诊断 ISO + PAGER=off）。</li><li>dhtest 5/5（2048 位 modexp 真值）+ <code>uname -r</code> = 3.0.0-WP-severe-fix-and-closure。</li><li>OCIRE 电池 14/14（七个 UEFI 场景 + 七个 BIOS 场景）。</li><li>HTTPS E2E 8/8；SSH E2E 出站场景 PASS（入站 sshd 为 K-09 申报余留边界）。</li><li>update 全链电池 10/10（本文件第 ⑤ 节）。</li></ul><h2 id="sha256" tabindex="-1">SHA256 <a class="header-anchor" href="#sha256" aria-label="Permalink to &quot;SHA256&quot;">​</a></h2><blockquote><p>注：本表摘要生成于回滚前（已撤销）的命名期；资产名已按版本规约回滚为 <code>3.0.0-WP-severe-fix-and-closure</code>，最终摘要由 <code>tools/update_website.sh</code> 在重建后回填。</p></blockquote><table tabindex="0"><thead><tr><th>资产</th><th>SHA256</th></tr></thead><tbody><tr><td>opencube-3.0.0-WP-severe-fix-and-closure.iso</td><td><code>e4bfd7107971486714a8d08003d398d557d447448f4209a81b6430acd32b2e3d</code></td></tr><tr><td>opencube-3.0.0-WP-severe-fix-and-closure-src.zip</td><td><code>b9267dafe24ac441f9918600a9a2a383535223618398cc83e3946cf6446b60f9</code></td></tr><tr><td>opencube-3.0.0-WP-severe-fix-and-closure-update.tar.gz</td><td><code>26c7e7cd3742186dafd1f2b4d161881106afa6c3ed5a93a6be178d23324c426a</code></td></tr></tbody></table><h2 id="已知事项" tabindex="-1">已知事项 <a class="header-anchor" href="#已知事项" aria-label="Permalink to &quot;已知事项&quot;">​</a></h2><ul><li><strong>K-08 / K-10 已关闭</strong>（本包根因化修复，KNOWN_ISSUES 相应改写）。</li><li><strong>K-09 已按&quot;误诊&quot;关闭</strong>，唯一余留边界：入站 sshd 场景（时序相关滞留， pcap + monitor 转储 + TX-errors 计数器证据齐备，KNOWN_ISSUES 诚实记录）。</li><li>沙箱无法运行 VMware——① 为结构性修复（计数器证明负载削减 446/1116 倍）；VMware 实机复测为用户侧验收项（计数行在每次启动的串口 transcript 上）。</li><li>EFI 链接的 ld RWX 段警告为历史已申报预存在项（wp06g1 起）；<code>make test</code> 的 19 个主机侧用例构建失败为 K-01 继承项（申报未静默）。</li><li>K-01/K-02/K-03/K-05/K-06/K-07 沿袭不变（见 KNOWN_ISSUES）。</li></ul>',22)])])}const _=o(s,[["render",d]]);export{p as __pageData,_ as default};
